898	+func collectSiblingAutoAdoptCandidates(
899	+	ctx context.Context,
900	+	targetWorktree, targetCommonDir string,
901	+	staged []string,
902	+	owner proclive.Identity,
903	+	hasOwner bool,
904	+) []autoAdoptCandidate {
