964	+) (autoAdoptCandidate, bool) {
965	+	store, worktree, commonDir, err := stateStoreForWorktree(ctx, sourceWorktree)
966	+	if err != nil {
967	+		return autoAdoptCandidate{}, false
968	+	}
969	+	state, err := store.Load(ctx, sessionID)
970	+	if err != nil || state == nil {
