976	+func candidateFromLoaded(
977	+	store *session.StateStore,
978	+	worktree, commonDir string,
979	+	state *session.State,
980	+	staged []string,
981	+	owner proclive.Identity,
982	+	hasOwner bool,
983	+) (autoAdoptCandidate, bool) {
984	+	if !isRecentAdoptCandidate(state) {
985	+		return autoAdoptCandidate{}, false
986	+	}
987	+	// Auto-adopt is ACTIVE-only (matches live-registry prefilter and the feature doc).
988	+	// Idle is adoptable manually but must not be silently relocated on a commit hook.
989	+	if state.Phase != session.PhaseActive {
990	+		return autoAdoptCandidate{}, false
991	+	}
992	+	// Reject stale WorktreePath mismatches. Overriding worktree with
993	+	// state.WorktreePath would make sessionBelongsToSourceWorktree a tautology
994	+	// (comparing the recorded path against itself) and miss the ownership check.
995	+	if state.WorktreePath != "" && !sameAdoptPath(state.WorktreePath, worktree) {
996	+		return autoAdoptCandidate{}, false
997	+	}
998	+	// Both owner match and distinctive FilesTouched overlap are required.
999	+	// Boilerplate-only overlap (README.md, go.mod, …) is ignored even when
1000	+	// the owner matches — those names collide across unrelated siblings.
1001	+	overlapMatch := filesTouchedOverlap(state.FilesTouched, staged)
1002	+	if !overlapMatch {
1003	+		return autoAdoptCandidate{}, false
1004	+	}
1005	+	ownerMatch := hasOwner && ownerMatches(state.Owner, owner)
1006	+	if !ownerMatch {
1007	+		return autoAdoptCandidate{}, false
1008	+	}
1009	+	return autoAdoptCandidate{
1010	+		SessionID:    state.SessionID,
1011	+		WorktreePath: worktree,
1012	+		CommonDir:    commonDir,
1013	+		Store:        store,
1014	+		OwnerMatch:   ownerMatch,
1015	+		OverlapMatch: overlapMatch,
1016	+	}, true
1017	+}
