1024	+		return false
1025	+	}
1026	+	// LiveSessionMaxAge matches adoptRecentWindow; registry TTL sweep uses the same bound.
1027	+	return time.Since(*entry.LastInteractionTime) <= session.LiveSessionMaxAge
